CREATE TYPE "UserRole" AS ENUM ('ADMIN','OPERATOR');
CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT','ACTIVE','PAUSED','FINISHED','ARCHIVED');
CREATE TYPE "CampaignContactStatus" AS ENUM ('PENDING','SENT','NOT_SENT','NO_WHATSAPP','ERROR','SKIPPED');
CREATE TYPE "WhatsAppStatus" AS ENUM ('UNVERIFIED','CONFIRMED','NO_WHATSAPP','ERROR');
CREATE TYPE "ImportStatus" AS ENUM ('PREVIEW','PROCESSING','COMPLETED','FAILED');
CREATE TYPE "MessageEventType" AS ENUM ('OPENED_WHATSAPP','SENT','NOT_SENT','NO_WHATSAPP','ERROR','SKIPPED');
CREATE TABLE "users" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"role" "UserRole" NOT NULL DEFAULT 'OPERATOR',"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "campaigns" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT,"default_url" TEXT,"message_template" TEXT,"status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',"owner_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "contacts" ("id" TEXT PRIMARY KEY,"name" TEXT,"phone" TEXT NOT NULL,"email" TEXT,"city" TEXT,"state" TEXT,"cpf" TEXT,"notes" TEXT,"custom_fields" JSONB NOT NULL DEFAULT '{}',"whatsapp_status" "WhatsAppStatus" NOT NULL DEFAULT 'UNVERIFIED',"anonymized_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "campaign_contacts" ("id" TEXT PRIMARY KEY,"campaign_id" TEXT NOT NULL,"contact_id" TEXT NOT NULL,"custom_fields" JSONB NOT NULL DEFAULT '{}',"generated_message" TEXT,"generated_url" TEXT,"status" "CampaignContactStatus" NOT NULL DEFAULT 'PENDING',"sent_at" TIMESTAMP(3),"sent_by" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "imports" ("id" TEXT PRIMARY KEY,"campaign_id" TEXT NOT NULL,"file_name" TEXT NOT NULL,"status" "ImportStatus" NOT NULL DEFAULT 'PREVIEW',"mapping" JSONB NOT NULL DEFAULT '{}',"summary" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completed_at" TIMESTAMP(3));
CREATE TABLE "import_rows" ("id" TEXT PRIMARY KEY,"import_id" TEXT NOT NULL,"row_number" INTEGER NOT NULL,"raw_data" JSONB NOT NULL,"normalized_data" JSONB,"errors" JSONB NOT NULL DEFAULT '[]',"imported" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "message_templates" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"category" TEXT,"message" TEXT NOT NULL,"variables" JSONB NOT NULL DEFAULT '[]',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "message_events" ("id" TEXT PRIMARY KEY,"campaign_id" TEXT NOT NULL,"contact_id" TEXT NOT NULL,"campaign_contact_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"event_type" "MessageEventType" NOT NULL,"message" TEXT,"url" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "audit_logs" ("id" TEXT PRIMARY KEY,"user_id" TEXT,"action" TEXT NOT NULL,"entity" TEXT,"entity_id" TEXT,"ip" TEXT,"metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "settings" ("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL,"value" JSONB NOT NULL,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE UNIQUE INDEX "contacts_phone_key" ON "contacts"("phone"); CREATE UNIQUE INDEX "settings_key_key" ON "settings"("key");
CREATE INDEX "campaigns_status_created_at_idx" ON "campaigns"("status","created_at"); CREATE INDEX "campaigns_owner_id_idx" ON "campaigns"("owner_id"); CREATE INDEX "contacts_name_idx" ON "contacts"("name"); CREATE INDEX "contacts_created_at_idx" ON "contacts"("created_at");
CREATE INDEX "campaign_contacts_campaign_id_status_created_at_idx" ON "campaign_contacts"("campaign_id","status","created_at"); CREATE INDEX "campaign_contacts_contact_id_idx" ON "campaign_contacts"("contact_id"); CREATE UNIQUE INDEX "campaign_contacts_campaign_id_contact_id_key" ON "campaign_contacts"("campaign_id","contact_id");
CREATE INDEX "imports_campaign_id_created_at_idx" ON "imports"("campaign_id","created_at"); CREATE INDEX "import_rows_import_id_imported_idx" ON "import_rows"("import_id","imported"); CREATE UNIQUE INDEX "import_rows_import_id_row_number_key" ON "import_rows"("import_id","row_number");
CREATE INDEX "message_events_campaign_id_created_at_idx" ON "message_events"("campaign_id","created_at"); CREATE INDEX "message_events_contact_id_created_at_idx" ON "message_events"("contact_id","created_at"); CREATE INDEX "message_events_user_id_created_at_idx" ON "message_events"("user_id","created_at"); CREATE INDEX "audit_logs_user_id_created_at_idx" ON "audit_logs"("user_id","created_at"); CREATE INDEX "audit_logs_entity_entity_id_idx" ON "audit_logs"("entity","entity_id");
ALTER TABLE "campaigns" ADD CONSTRAINT "campaigns_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "campaign_contacts" ADD CONSTRAINT "campaign_contacts_campaign_id_fkey" FOREIGN KEY ("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "campaign_contacts" ADD CONSTRAINT "campaign_contacts_contact_id_fkey" FOREIGN KEY ("contact_id") REFERENCES "contacts"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "campaign_contacts" ADD CONSTRAINT "campaign_contacts_sent_by_fkey" FOREIGN KEY ("sent_by") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "imports" ADD CONSTRAINT "imports_campaign_id_fkey" FOREIGN KEY ("campaign_id") REFERENCES "campaigns"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "import_rows" ADD CONSTRAINT "import_rows_import_id_fkey" FOREIGN KEY ("import_id") REFERENCES "imports"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "message_events" ADD CONSTRAINT "message_events_campaign_id_fkey" FOREIGN KEY ("campaign_id") REFERENCES "campaigns"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "message_events" ADD CONSTRAINT "message_events_contact_id_fkey" FOREIGN KEY ("contact_id") REFERENCES "contacts"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "message_events" ADD CONSTRAINT "message_events_campaign_contact_id_fkey" FOREIGN KEY ("campaign_contact_id") REFERENCES "campaign_contacts"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "message_events" ADD CONSTRAINT "message_events_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
